input.newString:
  }, 10_000);

  it('forwards allowedMentions { parse: [] } to channel.send', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi.fn();
    const client = fakeClientWithChannelSend(send);

    await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(send).toHaveBeenCalledWith(expect.any(String), expect.objectContaining({
      allowedMentions: { parse: [] },
    }));
  });

  it('forwards allowedMentions { parse: [] } to user.send for DM delivery', async () => {
    const dmServerRow: NewServerRow = {
      ...serverRow,
      digestMode: 'dm',
      adminChannelId: null,
      digestDmUserId: 'user-999',
    };
    getDb().insert(servers).values(dmServerRow).run();
    addListing();

    const userSend = vi.fn();
    const userFetch = vi.fn().mockResolvedValue({
      send: userSend,
    });
    const client = {
      users: {
        fetch: userFetch,
      },
    } as unknown as Client;

    await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(userFetch).toHaveBeenCalledWith('user-999');
    expect(userSend).toHaveBeenCalledWith(
      expect.any(String),
      expect.objectContaining({
        allowedMentions: { parse: [] },
      }),
    );
  });

  it('attempts retry on DM send failure before giving up', async () => {
    const dmServerRow: NewServerRow = {
      ...serverRow,
      digestMode: 'dm',
      adminChannelId: null,
      digestDmUserId: 'user-999',
    };
    getDb().insert(servers).values(dmServerRow).run();
    addListing();

    const userSend = vi
      .fn()
      .mockRejectedValueOnce(new Error('transient error'))
      .mockRejectedValue(new Error('persistent error'));
    const userFetch = vi.fn().mockResolvedValue({
      send: userSend,
    });
    const client = {
      users: {
        fetch: userFetch,
      },
    } as unknown as Client;

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.channelOk).toBe(false);
    expect(result.dmOk).toBe(false);
    expect(userSend).toHaveBeenCalledTimes(3);
    expect(getServerConfig('500')!.lastDigestAt).toBe(0);
  }, 10_000);
});

